def transform(grid):
    """Move all non-background cells down by one row."""
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out
